#include <bits/stdc++.h>
using namespace std;

struct Node { int id; double x, y; char type; };

int par[6002], rnk_[6002];
int find_(int x){return par[x]==x?x:par[x]=find_(par[x]);}
bool unite_(int a,int b){a=find_(a);b=find_(b);if(a==b)return false;if(rnk_[a]<rnk_[b])swap(a,b);par[b]=a;if(rnk_[a]==rnk_[b])rnk_[a]++;return true;}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N,K;
    cin>>N>>K;

    vector<Node> nd(N+K);
    map<int,int> idToIdx;
    for(int i=0;i<N+K;i++){
        cin>>nd[i].id>>nd[i].x>>nd[i].y>>nd[i].type;
        idToIdx[nd[i].id]=i;
    }

    vector<int> robots, relays;
    for(int i=0;i<N+K;i++){
        if(nd[i].type=='C') relays.push_back(i);
        else robots.push_back(i);
    }

    int NR=robots.size();

    auto dist2=[&](int i,int j)->double{
        double dx=nd[i].x-nd[j].x, dy=nd[i].y-nd[j].y;
        return dx*dx+dy*dy;
    };

    auto edgeCost=[&](int i,int j)->double{
        if(nd[i].type=='C'&&nd[j].type=='C') return 1e18;
        double D=dist2(i,j);
        if(nd[i].type!='C'&&nd[j].type!='C'){
            if(nd[i].type=='S'||nd[j].type=='S') return 0.8*D;
            return D;
        }
        return D;
    };

    // Prim's MST over robots only
    vector<double> key(NR,1e18);
    vector<int> parent(NR,-1);
    vector<bool> inMST(NR,false);
    key[0]=0;
    for(int iter=0;iter<NR;iter++){
        int u=-1;
        for(int i=0;i<NR;i++)
            if(!inMST[i]&&(u==-1||key[i]<key[u])) u=i;
        inMST[u]=true;
        for(int v=0;v<NR;v++){
            if(!inMST[v]){
                double c=edgeCost(robots[u],robots[v]);
                if(c<key[v]){key[v]=c;parent[v]=u;}
            }
        }
    }

    struct Edge{int u,v;double w;};
    vector<Edge> edges;
    for(int i=1;i<NR;i++){
        double c=edgeCost(robots[i],robots[parent[i]]);
        edges.push_back({robots[i],robots[parent[i]],c});
    }

    // Try relay insertion: replace edge with two edges through relay if cheaper
    set<int> usedRelays;
    for(auto& ri:relays){
        int bestE=-1; double bestSave=-1e18;
        for(int e=0;e<(int)edges.size();e++){
            double nc=edgeCost(edges[e].u,ri)+edgeCost(edges[e].v,ri);
            double save=edges[e].w-nc;
            if(save>bestSave){bestSave=save;bestE=e;}
        }
        if(bestE>=0&&bestSave>1e-9){
            int u=edges[bestE].u,v=edges[bestE].v;
            edges[bestE]={u,ri,edgeCost(u,ri)};
            edges.push_back({ri,v,edgeCost(ri,v)});
            usedRelays.insert(ri);
        }
    }

    if(usedRelays.empty()) cout<<"#\n";
    else{
        bool f=true;
        for(int c:usedRelays){if(!f)cout<<"#";cout<<nd[c].id;f=false;}
        cout<<"\n";
    }
    {
        bool f=true;
        for(auto&e:edges){if(!f)cout<<"#";cout<<nd[e.u].id<<"-"<<nd[e.v].id;f=false;}
        cout<<"\n";
    }
}
